db.orders.aggregate([
  { $match: { status: 'DELIVERED', orderDate: { $gte: ISODate('2024-01-01'), $lt: ISODate('2025-01-01') } } },
  { $unwind: '$items' },
  { $lookup: { from: 'products', localField: 'items.product_id', foreignField: '_id', as: 'productInfo' } },
  { $unwind: '$productInfo' },
  { $group: {
      _id: '$productInfo.category',
      total_revenue: { $sum: { $multiply: [ '$items.quantity', '$items.unit_price' ] } },
      average_item_margin: { $avg: { $subtract: [ '$items.unit_price', '$productInfo.cost' ] } }
    }
  },
  { $sort: { total_revenue: -1 } },
  { $project: { _id: 0, category: '$_id', total_revenue: { $round: [ '$total_revenue', 2 ] }, average_item_margin: 1 } }
])
